   325→		SessionID:              opts.SessionID,
   326→		Strategy:               opts.Strategy,
   327→		CreatedAt:              time.Now(),
   328→		Branch:                 opts.Branch,
   329→		CheckpointsCount:       opts.CheckpointsCount,
   330→		FilesTouched:           opts.FilesTouched,
   331→		Agent:                  opts.Agent,
   332→		IsTask:                 opts.IsTask,
