// TestWriteCommitted_BranchField verifies that the Branch field is correctly
// captured in metadata.json when on a branch, and is empty when in detached HEAD.
// TestWriteCommitted_InitialAttribution verifies that the InitialAttribution field
// is correctly written to metadata.json when provided, and omitted when nil.
func TestWriteCommitted_InitialAttribution(t *testing.T) {
	t.Run("with attribution (manual-commit)", func(t *testing.T) {
		repo, _ := setupBranchTestRepo(t)
		store := NewGitStore(repo)

		checkpointID := id.MustCheckpointID("c3d4e5f6a7b8")

		// Write checkpoint with InitialAttribution (like manual-commit does)
		err := store.WriteCommitted(context.Background(), WriteCommittedOptions{
			CheckpointID: checkpointID,
			SessionID:    "test-session-manual",
			Strategy:     "manual-commit",
			Transcript:   []byte("test transcript"),
			AuthorName:   "Test Author",
			AuthorEmail:  "test@example.com",
			InitialAttribution: &InitialAttribution{
				AgentLines:      100,
				HumanAdded:      10,
				HumanModified:   5,
				HumanRemoved:    2,
				TotalCommitted:  110,
				AgentPercentage: 90.9,
			},
		})
		if err != nil {
			t.Fatalf("WriteCommitted() error = %v", err)
		}

		// Read metadata.json and verify InitialAttribution is present
		metadata := readMetadataJSON(t, repo, checkpointID)

		if metadata.InitialAttribution == nil {
			t.Fatal("expected InitialAttribution to be present, got nil")
		}
		if metadata.InitialAttribution.AgentLines != 100 {
			t.Errorf("AgentLines = %d, want 100", metadata.InitialAttribution.AgentLines)
		}
		if metadata.InitialAttribution.HumanAdded != 10 {
			t.Errorf("HumanAdded = %d, want 10", metadata.InitialAttribution.HumanAdded)
		}
		if metadata.InitialAttribution.HumanModified != 5 {
			t.Errorf("HumanModified = %d, want 5", metadata.InitialAttribution.HumanModified)
		}
		if metadata.InitialAttribution.HumanRemoved != 2 {
			t.Errorf("HumanRemoved = %d, want 2", metadata.InitialAttribution.HumanRemoved)
		}
		if metadata.InitialAttribution.TotalCommitted != 110 {
			t.Errorf("TotalCommitted = %d, want 110", metadata.InitialAttribution.TotalCommitted)
		}
		if metadata.InitialAttribution.AgentPercentage != 90.9 {
			t.Errorf("AgentPercentage = %f, want 90.9", metadata.InitialAttribution.AgentPercentage)
		}
	})

	t.Run("without attribution (auto-commit)", func(t *testing.T) {
		repo, _ := setupBranchTestRepo(t)
		store := NewGitStore(repo)

		checkpointID := id.MustCheckpointID("d4e5f6a7b8c9")

		// Write checkpoint without InitialAttribution (like auto-commit does)
		err := store.WriteCommitted(context.Background(), WriteCommittedOptions{
			CheckpointID: checkpointID,
			SessionID:    "test-session-auto",
			Strategy:     "auto-commit",
			Transcript:   []byte("test transcript"),
			AuthorName:   "Test Author",
			AuthorEmail:  "test@example.com",
			// InitialAttribution is nil (not set)
		})
		if err != nil {
			t.Fatalf("WriteCommitted() error = %v", err)
		}

		// Read metadata.json and verify InitialAttribution is omitted
		metadata := readMetadataJSON(t, repo, checkpointID)

		if metadata.InitialAttribution != nil {
			t.Errorf("expected InitialAttribution to be nil for auto-commit, got %+v", metadata.InitialAttribution)
		}

		// Also verify the JSON doesn't contain the field at all (omitempty)
		content := readMetadataJSONRaw(t, repo, checkpointID)
		if strings.Contains(content, "initial_attribution") {
			t.Errorf("metadata.json should not contain 'initial_attribution' when nil (omitempty), got:\n%s", content)
		}
	})
}

// readMetadataJSON reads and parses metadata.json for a checkpoint.
func readMetadataJSON(t *testing.T, repo *git.Repository, checkpointID id.CheckpointID) CommittedMetadata {
	t.Helper()
	content := readMetadataJSONRaw(t, repo, checkpointID)

	var metadata CommittedMetadata
	if err := json.Unmarshal([]byte(content), &metadata); err != nil {
		t.Fatalf("failed to parse metadata.json: %v", err)
	}
	return metadata
}

// readMetadataJSONRaw reads the raw metadata.json content for a checkpoint.
func readMetadataJSONRaw(t *testing.T, repo *git.Repository, checkpointID id.CheckpointID) string {
	t.Helper()

	ref, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	if err != nil {
		t.Fatalf("failed to get metadata branch reference: %v", err)
	}

	commit, err := repo.CommitObject(ref.Hash())
	if err != nil {
		t.Fatalf("failed to get commit object: %v", err)
	}

	tree, err := commit.Tree()
	if err != nil {
		t.Fatalf("failed to get tree: %v", err)
	}

	shardedPath := checkpointID.Path()
	metadataPath := shardedPath + "/" + paths.MetadataFileName
	metadataFile, err := tree.File(metadataPath)
	if err != nil {
		t.Fatalf("failed to find metadata.json at %s: %v", metadataPath, err)
	}

	content, err := metadataFile.Contents()
	if err != nil {
		t.Fatalf("failed to read metadata.json: %v", err)
	}

	return content
}

